use std::{collections::BTreeMap,fs};
fn main(){let mut all=BTreeMap::<(usize,usize),Vec<Vec<String>>>::new();for l in fs::read_to_string("research/hec_residual_span_20261116/incidence-oracle/RANK.tsv").unwrap().lines().skip(1){let v:Vec<String>=l.split('\t').map(str::to_string).collect();assert_eq!(v.len(),10);all.entry((v[0].parse().unwrap(),v[1].parse().unwrap())).or_default().push(v);}assert_eq!(all.len(),6);println!("p\tsm\tcores\tcompleted\tmin_first_rows\tmax_first_rows\tmin_first_anchor\tmax_first_anchor\tcore0_rows\tcore0_anchor\tfinal_full_rank_cores");for((p,sm),v)in all{let n=|i:usize,j:usize|v[i][j].parse::<usize>().unwrap();let complete=v.iter().filter(|r|r[8]!="none").count();let minrow=(0..v.len()).map(|i|n(i,6)).min().unwrap();let maxrow=(0..v.len()).map(|i|n(i,6)).max().unwrap();let minanchor=(0..v.len()).map(|i|n(i,7)).min().unwrap();let maxanchor=(0..v.len()).map(|i|n(i,7)).max().unwrap();let full=(0..v.len()).filter(|&i|n(i,9)==n(i,3)+1).count();assert_eq!(n(0,2),0);println!("{p}\t{sm}\t{}\t{complete}\t{minrow}\t{maxrow}\t{minanchor}\t{maxanchor}\t{}\t{}\t{full}",v.len(),n(0,6),n(0,7));}}
